const items = $input.all();
const now = new Date();
const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();
const endOfToday = startOfToday + 24*3600*1000;
const ADMIN_WHATSAPP = '2547XXXXXXXX';
const adminList = [];
const byAssignee = {};
for (const item of items) {
  const task = item.json;
  if (!task.id) continue;
  const desc = task.description || task.text_content || '';
  const m = desc.match(/\[BOTMETA\]([\s\S]*?)\[\/BOTMETA\]/);
  let meta = {};
  if (m) { try { meta = JSON.parse(m[1]); } catch(e) { meta = {}; } }
  const isClosed = task.status && task.status.type === 'closed';
  if (isClosed) continue;
  const dueMs = task.due_date ? Number(task.due_date) : null;
  if (!dueMs) continue;
  const isDueToday = dueMs >= startOfToday && dueMs < endOfToday;
  const isOverdue = dueMs < startOfToday;
  if (!isDueToday && !isOverdue) continue;
  const dueText = new Date(dueMs).toDateString();
  const priorityName = (task.priority && task.priority.priority) ? task.priority.priority : 'normal';
  const line = '- ' + task.name + ' (priority: ' + priorityName + ', due: ' + dueText + (isOverdue ? ', OVERDUE' : ', due today') + ')';
  adminList.push(line);
  if (meta.assignee_whatsapp) {
    if (!byAssignee[meta.assignee_whatsapp]) byAssignee[meta.assignee_whatsapp] = [];
    byAssignee[meta.assignee_whatsapp].push(line);
  }
}
const out = [];
if (adminList.length) {
  out.push({ json: { whatsapp_payload: { messaging_product:'whatsapp', to: ADMIN_WHATSAPP, type:'text', text: { body: 'Daily digest - tasks due today or overdue (' + adminList.length + '):\n' + adminList.join('\n') } } } });
}
for (const wa in byAssignee) {
  if (wa === ADMIN_WHATSAPP) continue;
  const lines2 = byAssignee[wa];
  out.push({ json: { whatsapp_payload: { messaging_product:'whatsapp', to: wa, type:'text', text: { body: 'Your tasks due today or overdue (' + lines2.length + '):\n' + lines2.join('\n') } } } });
}
return out;
